def bsearch(arr, key):
    lo, hi = 0, len(arr) - 1
    probes = 0
    while lo <= hi:
        mid = (lo + hi) // 2
        probes += 1
        if arr[mid] == key:
            return mid, probes
        elif arr[mid] < key:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1, probes
arr = [4, 9, 15, 21, 28, 34, 40, 47, 55, 63, 70, 78, 86, 93]
print(bsearch(arr, 60))  # (-1, 4)
